<template><div><PageHeader eyebrow="Product Configuration" :title="isNew?'新建套餐':`编辑${form.name||''}套餐`" :description="isNew?'创建新的可订阅套餐':`套餐编码 ${form.code||'—'} · 最近更新于 ${form.updatedAt||'—'}`"><router-link class="layui-btn monitor-secondary" to="/plans">返回列表</router-link></PageHeader><form class="panel plan-form" @submit.prevent="save"><section class="form-section"><h2>基础信息</h2><div class="form-grid"><div class="field" :class="{invalid:errors.name}"><label for="planName">套餐名称 *</label><input id="planName" v-model.trim="form.name" class="layui-input"><p v-if="errors.name" class="error-text">{{errors.name}}</p></div><div class="field" :class="{invalid:errors.code}"><label for="planCode">套餐编码 *</label><input id="planCode" v-model.trim="form.code" class="layui-input" :disabled="!isNew"><p class="helper">创建后不可修改，仅支持大写字母、数字和下划线</p><p v-if="errors.code" class="error-text">{{errors.code}}</p></div><div class="field full" :class="{invalid:errors.description}"><label for="description">套餐描述 *</label><textarea id="description" v-model.trim="form.description" class="layui-textarea"></textarea><p v-if="errors.description" class="error-text">{{errors.description}}</p></div></div></section><section class="form-section"><h2>计费与权益</h2><div class="form-grid"><div class="field"><label>计费周期 *</label><select v-model="form.billingCycle" class="layui-select"><option value="YEAR">按年</option><option value="MONTH">按月</option><option value="DAY">按天</option></select></div><div v-for="field in numberFields" :key="field.key" class="field" :class="{invalid:errors[field.key]}"><label>{{field.label}} *</label><input v-model.number="form[field.key]" class="layui-input" type="number" min="0"><p v-if="errors[field.key]" class="error-text">{{errors[field.key]}}</p></div></div></section><section class="form-section"><h2>发布状态</h2><div class="radio-cards"><label class="radio-card"><input v-model.number="form.status" type="radio" :value="1"><span><strong>立即上架</strong><br><small>企业可以购买或续费</small></span></label><label class="radio-card"><input v-model.number="form.status" type="radio" :value="0"><span><strong>暂时下架</strong><br><small>禁止新购但保留已有订阅</small></span></label></div><div class="field reason-field"><label>变更原因 *</label><textarea v-model.trim="form.reason" class="layui-textarea"></textarea><p v-if="errors.reason" class="error-text">{{errors.reason}}</p></div></section><footer class="form-footer"><router-link class="layui-btn monitor-secondary" to="/plans">取消</router-link><button class="layui-btn monitor-primary" :disabled="submitting">{{submitting?'保存中…':'保存修改'}}</button></footer></form><AppToast :message="toastMessage" :type="toastType" /></div></template>
<script>import PageHeader from '@/components/PageHeader.vue';import AppToast from '@/components/AppToast.vue';import feedback from '@/mixins/feedback';import { planApi } from '@/api/monitor';const empty=()=>({code:'',name:'',description:'',billingCycle:'YEAR',durationDays:365,price:0,listPrice:0,memberLimit:10,sortOrder:10,status:0,reason:''});export default{name:'PlanEditPage',components:{PageHeader,AppToast},mixins:[feedback],data:()=>({form:empty(),errors:{},submitting:false,numberFields:[{key:'durationDays',label:'套餐时长（天）'},{key:'price',label:'销售价格（元）'},{key:'listPrice',label:'划线价格（元）'},{key:'memberLimit',label:'成员上限（人）'},{key:'sortOrder',label:'展示排序'}]}),computed:{isNew(){return this.$route.params.id==='new';}},mounted(){if(!this.isNew)planApi.detail(this.$route.params.id).then(data=>{this.form={...data,reason:''};});},methods:{validate(){const e={};if(!this.form.name)e.name='请输入套餐名称';if(!/^[A-Z0-9_]+$/.test(this.form.code))e.code='请输入有效套餐编码';if(!this.form.description)e.description='请输入套餐描述';['durationDays','memberLimit'].forEach(k=>{if(Number(this.form[k])<=0)e[k]='必须大于 0';});['price','listPrice','sortOrder'].forEach(k=>{if(Number(this.form[k])<0)e[k]='不能小于 0';});if(!this.form.reason)e.reason='请填写操作原因';this.errors=e;return !Object.keys(e).length;},async save(){if(!this.validate())return;this.submitting=true;try{if(this.isNew)await planApi.create(this.form);else await planApi.update(this.$route.params.id,this.form);this.notify('套餐已保存');setTimeout(()=>this.$router.push('/plans'),500);}catch(e){this.errorMessage(e);}finally{this.submitting=false;}}}};</script><style scoped>.plan-form{max-width:920px}.form-footer{display:flex;justify-content:flex-end;gap:8px;padding:16px 20px;border-top:1px solid var(--border)}.reason-field{margin-top:18px}</style>
